#include <iostream>
#include <string>
#include <vector>

enum class Estado {
    preparado,
    enviado,
    cancelado
};

struct PedidoInvalido {};

class Pedido {
public:
    Pedido(std::string codigo, int unidades)
        : codigo_{codigo}, unidades_{unidades} {
        if (codigo_.empty() || unidades_ < 1 || unidades_ > 20) {
            throw PedidoInvalido{};
        }
    }

    std::string codigo() const {
        return codigo_;
    }

    int unidades() const {
        return unidades_;
    }

    Estado estado() const {
        return estado_;
    }

private:
    std::string codigo_;
    int unidades_;
    Estado estado_ = Estado::preparado;
};

int main() {
    Pedido pedido{"P2", 6};

    std::cout << pedido.codigo() << ":" << pedido.unidades()
              << " " << (pedido.estado() == Estado::preparado);

    return 0;
}

